mapper.select:
SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT_MESSAGE
WHERE CHAT_ID = #{id}

    AND NUM >= #{minNum}


    AND NUM <= #{maxNum}


    AND CREATED_AT >= #{minTimestamp}


    AND CREATED_AT <= #{maxTimestamp}

SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT_MESSAGE
WHERE CHAT_ID = #{chatId} AND NUM = #{num}
